Let’s see basic recursion examples:

**Factorial**
```js
function factorial(n) {
  if (n === 0) return 1; // base case
  return n * factorial(n - 1); // recursive case
}

console.log(factorial(5)); // 120
```

**Fibonacci (naive approach)**
```js
function fib(n) {
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2);
}

console.log(fib(6)); // 8
```

**Head Recursion**: Recursive call happens **before** processing.

```js
function countdown(n) {
  if (n === 0) return;
  countdown(n - 1);
  console.log(n);
}
```

**Tail Recursion**: Recursive call is the **last statement**.

```js
function countdown(n) {
  if (n === 0) return;
  console.log(n);
  countdown(n - 1);
}
```

Tail recursion can be optimized in some languages (not JavaScript yet) by compilers to avoid stack overflow.

Always make sure recursive calls converge to the base case to avoid infinite loops.

Binary trees are perfect for recursion because each subtree is a smaller instance of the tree.

```js
class TreeNode {
  constructor(val) {
    this.val = val;
    this.left = null;
    this.right = null;
  }
}

function inorder(node) {
  if (!node) return;
  inorder(node.left);
  console.log(node.val);
  inorder(node.right);
}

function preorder(node) {
  if (!node) return;
  console.log(node.val);
  preorder(node.left);
  preorder(node.right);
}

function postorder(node) {
  if (!node) return;
  postorder(node.left);
  postorder(node.right);
  console.log(node.val);
}
```

**Recursive Binary Search**
```js
function binarySearch(arr, target, low = 0, high = arr.length - 1) {
  if (low > high) return -1;
  const mid = Math.floor((low + high) / 2);

  if (arr[mid] === target) return mid;
  if (arr[mid] > target) return binarySearch(arr, target, low, mid - 1);
  return binarySearch(arr, target, mid + 1, high);
}

console.log(binarySearch([1, 3, 5, 7, 9], 5)); // 2
```

**Iterative Binary Search**
```js
function binarySearchIterative(arr, target) {
  let low = 0, high = arr.length - 1;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) low = mid + 1;
    else high = mid - 1;
  }
  return -1;
}
```

```js
function mergeSort(arr) {
  if (arr.length <= 1) return arr;

  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));

  return merge(left, right);
}

function merge(left, right) {
  let result = [], i = 0, j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] < right[j]) {
      result.push(left[i++]);
    } else {
      result.push(right[j++]);
    }
  }
  return result.concat(left.slice(i)).concat(right.slice(j));
}

console.log(mergeSort([3, 1, 4, 2])); // [1, 2, 3, 4]
```

```js
function quickSort(arr) {
  if (arr.length <= 1) return arr;

  const pivot = arr[arr.length - 1];
  const left = [], right = [];

  for (let i = 0; i < arr.length - 1; i++) {
    if (arr[i] < pivot) left.push(arr[i]);
    else right.push(arr[i]);
  }

  return [...quickSort(left), pivot, ...quickSort(right)];
}

console.log(quickSort([4, 2, 7, 1, 3])); // [1, 2, 3, 4, 7]
```

Recursive solutions can be expensive if they repeat work. **Memoization** helps by storing already-computed results.

**Example: Optimized Fibonacci**
```js
function fib(n, memo = {}) {
  if (n <= 1) return n;
  if (memo[n]) return memo[n];
  memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
  return memo[n];
}
```

**Time Complexity Analysis**:
- Naive recursion (Fibonacci): O(2^n)
- Memoized recursion: O(n)
- Merge Sort: O(n log n)
- Quick Sort (avg): O(n log n), worst-case O(n^2)
- Binary Search: O(log n)
